import {MODULES,LABELS} from './modules.js';
import {SCHOOL,ROLES,esc,money,today,grade,parseCSV,csvCell,validateData,canWrite} from './core.js';
import {store,configured,saveConfig,signIn,signUp,restore,signOut,loadRecords,records,saveRecord,deleteRecord,rpc,request,startDemo} from './data.js';
const $=s=>document.querySelector(s);let page='dashboard',search='',roomFilter='',statusFilter='',pageIndex=0,loginMode='login',busy=false;
const PAGE_SIZE=25;let toastTimer;
const icon=(name='grid',size=19)=>{const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',book:'<path d="M12 21V5M3 3l9 2 9-2v16l-9 2-9-2z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2M14 15h2"/>',check:'<path d="M20 6 9 17l-5-5"/>',money:'<rect x="2" y="5" width="20" height="14" rx="2"/><circle cx="12" cy="12" r="3"/><path d="M6 12h.01M18 12h.01"/>',chart:'<path d="M4 3v18h18M8 16v-5M13 16V7M18 16v-9"/>',settings:'<path d="m9 3-1 3-3 1v4l-2 1 2 2v3l3 1 1 3h5l1-3 3-1v-3l3-2-3-1V7l-3-1-1-3z"/><circle cx="11.5" cy="12" r="3"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h6"/>',arrow:'<path d="M5 12h14M12 5l7 7-7 7"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',logout:'<path d="M9 5H4v14h5M14 8l4 4-4 4M8 12h10"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6zM8 12l3 3 5-6"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.file}</svg>`};
const groupIcons={'ข้อมูลพื้นฐาน':'users','งานวิชาการ':'book','ดูแลช่วยเหลือนักเรียน':'shield','งานบุคลากร':'users','แผนงานและงบประมาณ':'money','งานพัสดุและจัดซื้อ':'file','งานทั่วไป':'calendar'};
const micon=k=>icon(groupIcons[MODULES.find(m=>m.key===k)?.group]||'file');
const label=k=>LABELS[k]||({i1:'ข้อที่ 1',r_bmi:'ผลเกณฑ์ BMI'}[k])||(/^[ict]\d+$/.test(k)?'ข้อที่ '+k.slice(1):k.replaceAll('_',' '));
const badge=s=>`<span class="status ${/ร่าง|รอ|ยื่น|เสนอ/.test(s)?'warn':/ปฏิเสธ|ไม่อนุมัติ|ขาด|ชำรุด/.test(s)?'bad':''}">${esc(s||'—')}</span>`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function closeModal(){$('#modal').innerHTML=''}
function modal(title,body,footer='',wide=false){$('#modal').innerHTML=`<div class="modalbg"><section class="modalbox" role="dialog" aria-modal="true" aria-label="${esc(title)}" ${wide?'style="width:min(1050px,100%)"':''}><div class="modalhead"><h2>${esc(title)}</h2><button class="btn light small" data-act="close" aria-label="ปิดหน้าต่าง">✕</button></div><div class="modalbody">${body}</div>${footer?`<div class="modalfoot">${footer}</div>`:''}</section></div>`;setTimeout(()=>$('#modal input, #modal select, #modal button')?.focus(),0)}
const button=(text,act,cls='light',extra='')=>`<button class="btn ${cls}" data-act="${act}" ${extra}>${text}</button>`;
const art=()=>'<div class="hero-art" aria-hidden="true"><div class="sun"></div><div class="building"><div class="roof"></div><div class="windows">'+Array(8).fill('<i></i>').join('')+'</div><div class="door"></div></div></div>';
function login(){const connected=configured();$('#app').innerHTML=`<main class="login-layout"><section class="login-hero"><div class="login-brand"><div class="crest">สว</div><div><strong>สามัคคีศรีวิชัย</strong><div style="font-size:10px;letter-spacing:2px;color:#d0e0ca">SCHOOL MANAGEMENT SYSTEM</div></div></div><div><div class="eyebrow" style="color:var(--yellow)">TOGETHER, WE GROW.</div><h1>เชื่อมทุกงานโรงเรียน<br>เพื่อการเรียนรู้ที่ดีกว่า</h1><p>จัดการข้อมูล วางแผน และดูแลนักเรียน<br>ในพื้นที่ทำงานเดียวสำหรับทุกคนในโรงเรียน</p></div>${art()}<footer style="font-size:10px;color:#b4cec0">${SCHOOL} · ระบบบริหารจัดการโรงเรียน</footer></section><section class="login-form"><div class="login-inner"><div class="eyebrow">ยินดีต้อนรับสู่ SCHOOL OS</div><h2>${loginMode==='login'?'เข้าสู่ระบบโรงเรียน':'ขอเปิดบัญชีบุคลากร'}</h2><p class="sub">${loginMode==='login'?'ใช้บัญชีอีเมลที่ผู้ดูแลระบบอนุมัติให้คุณ':'บัญชีใหม่ต้องได้รับการกำหนดสิทธิ์จากผู้ดูแลระบบ'}</p><form id="loginForm">${loginMode==='signup'?'<div class="field"><label for="display_name">ชื่อ–นามสกุล</label><input id="display_name" name="display_name" autocomplete="name" required></div>':''}<div class="field"><label for="email">อีเมล</label><input id="email" name="email" type="email" autocomplete="username" placeholder="name@school.ac.th" required></div><div class="field"><label for="password">รหัสผ่าน</label><input id="password" name="password" type="password" autocomplete="${loginMode==='login'?'current-password':'new-password'}" minlength="8" placeholder="กรอกรหัสผ่านของคุณ" required></div><div id="loginErr" class="err" role="alert"></div><button class="btn" type="submit" ${!connected?'disabled':''}>${loginMode==='login'?'เข้าสู่ระบบ':'ขอเปิดบัญชี'} ${icon('arrow',16)}</button></form><p class="help" style="text-align:center;margin-top:17px"><button class="linkbtn" data-act="switchLogin">${loginMode==='login'?'ยังไม่มีบัญชี? ขอเปิดบัญชีบุคลากร':'มีบัญชีแล้ว? เข้าสู่ระบบ'}</button></p><div class="divider">หรือสำรวจระบบก่อนเริ่มใช้งาน</div><button class="btn light" data-act="demo" style="width:100%">${icon('grid',16)} ทดลองใช้ด้วยข้อมูลสาธิต</button><div class="connection"><div class="split"><span class="pill ${connected?'':'demo'}"><i class="dot"></i>${connected?'ตั้งค่าการเชื่อมต่อแล้ว':'ยังไม่ได้เชื่อมต่อฐานข้อมูล'}</span><button class="linkbtn" data-act="configure">ตั้งค่า</button></div><p class="help">${connected?'ระบบจะตรวจสอบบัญชีและสิทธิ์กับ Supabase เมื่อเข้าสู่ระบบ':'เชื่อมต่อ Supabase เพื่อเริ่มบันทึกข้อมูลจริงของโรงเรียน'}</p></div><div class="login-footer">${icon('shield',12)} ข้อมูลโรงเรียนเข้าถึงได้ตามสิทธิ์ที่ได้รับเท่านั้น</div></div></section></main>`}
function shell(){const groups=[...new Set(MODULES.map(m=>m.group))];const module=MODULES.find(m=>m.key===page);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="crest">สว</div><div><strong>สามัคคีศรีวิชัย</strong><small>SCHOOL OS</small></div></div><nav class="nav-scroll"><div class="nav-label">WORKSPACE</div><button class="navitem ${page==='dashboard'?'active':''}" data-page="dashboard"><span class="ico">${icon('grid')}</span>ภาพรวมโรงเรียน</button><button class="navitem ${page==='modules'?'active':''}" data-page="modules"><span class="ico">${icon('file')}</span>ระบบงานทั้งหมด <span style="margin-left:auto;font-size:10px">49</span></button><div class="nav-label" style="margin-top:24px">SCHOOL MANAGEMENT</div>${groups.map(g=>`<details class="navgroup" ${module?.group===g?'open':''}><summary>${icon(groupIcons[g],17)}${esc(g)}</summary>${MODULES.filter(m=>m.group===g).map(m=>`<button class="navitem ${page===m.key?'active':''}" data-page="${m.key}">${m.title}</button>`).join('')}</details>`).join('')}<div class="nav-label" style="margin-top:24px">MANAGEMENT</div><button class="navitem ${page==='reports'?'active':''}" data-page="reports">${icon('chart')}รายงานและสถิติ</button>${['admin','director'].includes(store.profile.role)?`<button class="navitem ${page==='users'?'active':''}" data-page="users">${icon('users')}ผู้ใช้และสิทธิ์</button><button class="navitem ${page==='audit'?'active':''}" data-page="audit">${icon('shield')}ประวัติการใช้งาน</button>`:''}<button class="navitem ${page==='settings'?'active':''}" data-page="settings">${icon('settings')}ตั้งค่าระบบ</button></nav><div class="sidebar-foot"><div class="userbox"><div class="avatar">${esc(store.profile.display_name?.slice(0,1)||'ส')}</div><div style="flex:1"><strong>${esc(store.profile.display_name||'บุคลากร')}</strong><small>${esc(ROLES[store.profile.role])}</small></div><button class="btn light small" data-act="logout" aria-label="ออกจากระบบ">${icon('logout',15)}</button></div></div></aside><main class="main"><header class="topbar"><button class="mobiletoggle" data-act="menu" aria-label="เปิดเมนู">${icon('menu')}</button><div class="breadcrumb">พื้นที่ทำงาน <span style="margin:0 12px;color:#c3ccc3">/</span> <span style="color:var(--ink)">${module?.title||({dashboard:'ภาพรวมโรงเรียน',modules:'ระบบงานทั้งหมด',settings:'ตั้งค่าระบบ',reports:'รายงานและสถิติ',users:'ผู้ใช้และสิทธิ์',audit:'ประวัติการใช้งาน'}[page])}</span></div><div class="top-actions"><span class="date" style="font-size:11px;color:var(--muted)">${new Date().toLocaleDateString('th-TH',{timeZone:'Asia/Bangkok',day:'numeric',month:'long',year:'numeric'})}</span><span class="pill ${store.demo?'demo':''}"><i class="dot"></i>${store.demo?'โหมดสาธิต':'Supabase เชื่อมต่อแล้ว'}</span><span class="pill">ปี ${esc(store.settings.academic_year)}</span></div></header><div class="content" id="content"></div></main></div>`}
function head(title,sub,action=''){return `<div class="pagehead"><div><div class="eyebrow">SAMAKKEE SRIWICHAI SCHOOL</div><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`}
function demoNotice(){return store.demo?`<div class="notice"><span>ข้อมูลสาธิตสำหรับทดลองเท่านั้น · การเปลี่ยนแปลงจะหายเมื่อโหลดหน้าใหม่</span>${button('เชื่อมต่อฐานข้อมูล','configure','light small')}</div>`:''}
function footer(){return `<footer class="page-footer"><span>${SCHOOL} · School Management System</span><span>เชื่อมโยงข้อมูล เพื่อพัฒนาการศึกษา</span></footer>`}
function setContent(html){$('#content').innerHTML=demoNotice()+html+footer()}
function dashboard(){const ss=records('Students').filter(r=>r.data.status==='กำลังศึกษา'),ts=records('Teachers'),ps=records('Projects'),es=records('ProjExpenses'),ats=records('Attendance').filter(r=>r.data.date===today());const attended=ats.reduce((a,r)=>a+Number(r.data.present||0)+Number(r.data.late||0),0),checked=ats.reduce((a,r)=>a+Number(r.data.total||0),0);const budget=ps.reduce((a,r)=>a+Number(r.data.budget_alloc||0)+Number(r.data.budget_activity||0),0),spent=es.reduce((a,r)=>a+Number(r.data.amount||0),0);const classes=[...new Set(ss.map(r=>r.data.class_level))].sort((a,b)=>a.localeCompare(b,'th',{numeric:true}));const counts=classes.map(c=>ss.filter(r=>r.data.class_level===c).length),max=Math.max(...counts,1);const events=records('Events').filter(r=>r.data.start_date>=today()).sort((a,b)=>a.data.start_date.localeCompare(b.data.start_date)).slice(0,4);const pending=records('ProjRequests').filter(r=>['ยื่นแล้ว','เสนอ ผอ.','อนุมัติ'].includes(r.data.status)).length;setContent(head('ภาพรวมโรงเรียน','ข้อมูลสำคัญของโรงเรียนในพื้นที่เดียว · ตามสิทธิ์การเข้าถึงของคุณ',button(icon('calendar',15)+' ปฏิทินโรงเรียน','nav','light','data-target="Events"'))+`<section class="hero"><div><div class="tagline">A GOOD DAY TO MAKE A DIFFERENCE</div><h2>ทุกก้าวของโรงเรียน เริ่มจากความร่วมมือ</h2><p>ยินดีต้อนรับสู่ระบบบริหาร${SCHOOL.replace('โรงเรียน','')}<br>พร้อมดูแลนักเรียนและขับเคลื่อนงานโรงเรียนไปด้วยกัน</p></div>${art()}</section><div class="stats">${[['นักเรียนทั้งหมด',ss.length,'คน','users','สถานะกำลังศึกษา'],['ครูและบุคลากร',ts.length,'คน','book','ข้อมูลบุคลากรในระบบ'],['การมาเรียนวันนี้',checked?Math.round(attended/checked*100)+'%':'—','','check',checked?`มาเรียน ${attended} จาก ${checked} คน`:'ยังไม่มีการเช็กชื่อวันนี้'],['งบประมาณโครงการ',money(budget),'บาท','money',`${ps.length} โครงการในปีการศึกษานี้`]].map(([l,v,u,i,h])=>`<div class="stat"><div class="iconbox">${icon(i,19)}</div><div class="label">${l}</div><div class="value">${v}<span class="unit">${u}</span></div><div class="hint">${h}</div></div>`).join('')}</div><div class="dashboard-grid"><div><section class="card"><div class="cardhead"><h3>จำนวนนักเรียนแยกตามระดับชั้น</h3><small>ปีการศึกษา ${esc(store.settings.academic_year)}</small></div><div class="chart-wrap"><div class="chart">${classes.length?classes.map((c,i)=>`<div class="baritem"><small>${counts[i]}</small><div class="bar" style="height:${Math.max(3,counts[i]/max*105)}px"></div><span>${esc(c)}</span></div>`).join(''):'<p class="help" style="margin:auto">ยังไม่มีข้อมูลนักเรียน</p>'}</div></div></section><section class="card"><div class="cardhead"><h3>เข้าถึงงานที่ใช้บ่อย</h3><button class="linkbtn" data-page="modules">ดูระบบทั้งหมด →</button></div><div class="quickgrid">${[['Attendance','check','เช็กชื่อรายวัน'],['Scores','book','บันทึกผลการเรียน'],['Students','users','ทะเบียนนักเรียน'],['Projects','money','แผนงาน / โครงการ']].map(([k,i,t])=>`<button class="quick" data-page="${k}">${icon(i,25)}${t}</button>`).join('')}</div></section></div><div><section class="card"><div class="cardhead"><h3>ปฏิทินและกิจกรรม</h3>${icon('calendar',17)}</div>${events.length?events.map(e=>`<div class="event"><div class="daybox">${esc(e.data.start_date?.slice(8))}<small>${new Date(e.data.start_date+'T12:00:00').toLocaleDateString('th-TH',{month:'short'})}</small></div><div><strong>${esc(e.data.title)}</strong><p>${esc(e.data.location||'ไม่ระบุสถานที่')}</p>${badge(e.data.category||'กิจกรรม')}</div></div>`).join(''):'<p class="help">ยังไม่มีกิจกรรมที่กำลังจะมาถึง</p>'}<button class="linkbtn" data-page="Events" style="margin-top:15px">เปิดปฏิทินทั้งหมด →</button></section><section class="card"><div class="cardhead"><h3>ติดตามงบประมาณ</h3><span class="pill">${ps.length} โครงการ</span></div><div class="split"><span>เบิกจ่ายแล้ว</span><strong style="color:var(--green)">${budget?Math.round(spent/budget*100):0}%</strong></div><div class="progress"><i style="width:${budget?Math.min(100,spent/budget*100):0}%"></i></div><div class="split"><span>${money(spent)} บาท</span><span>จาก ${money(budget)}</span></div><div style="border-top:1px solid var(--line);margin-top:18px;padding-top:15px" class="split"><span>คำขอที่รอดำเนินการ</span><button class="linkbtn" data-page="ProjRequests">${pending} รายการ →</button></div></section></div></div>`)}
function allModules(){setContent(head('ระบบงานทั้งหมด','เลือกงานที่ต้องการจัดการ · ข้อมูลถูกควบคุมด้วยสิทธิ์ในฐานข้อมูล')+[...new Set(MODULES.map(m=>m.group))].map(g=>`<h2 class="sectiontitle">${g}</h2><div class="modulecards">${MODULES.filter(m=>m.group===g).map(m=>`<button class="modulecard" data-page="${m.key}">${micon(m.key)}<h3>${m.title}</h3><p>${records(m.key).length} รายการ · ${canWrite(store.profile.role,m.key)?'จัดการข้อมูล':'ดูข้อมูล / ใช้ขั้นตอนเฉพาะ'}</p></button>`).join('')}</div>`).join(''))}
const readonlyKinds=['ProjRequests','ProjExpenses','Savings','SupplyLots','SupplyTransactions','BookLoans','AssetLoans'];
function filtered(){return records(page).filter(r=>(!search||JSON.stringify(r.data).toLowerCase().includes(search.toLowerCase()))&&(!roomFilter||r.class_id===roomFilter)&&(!statusFilter||r.data.status===statusFilter))}
function modulePage(){const m=MODULES.find(m=>m.key===page);const write=canWrite(store.profile.role,page);let action='';if(page==='ProjRequests')action=button(icon('plus',16)+' ยื่นคำขอเบิก','newRequest','');else if(page==='Savings')action=button(icon('plus',16)+' ฝาก / ถอนเงิน','saving','');else if(page==='SupplyTransactions')action=button(icon('plus',16)+' รับ / จ่ายวัสดุ','supply','');else if(['BookLoans','AssetLoans'].includes(page))action=button(icon('plus',16)+' บันทึกการยืม','loan','');else if(page==='Attendance')action=button(icon('check',16)+' เช็กชื่อรายห้อง','attendance','');else if(write)action=button(icon('plus',16)+' เพิ่มข้อมูล','new','');const rooms=[...new Set(records(page).map(r=>r.class_id).filter(Boolean))].sort();const statuses=[...new Set(records(page).map(r=>r.data.status).filter(Boolean))];setContent(head(m.title,m.group+' · ปีการศึกษา '+esc(store.settings.academic_year),action)+`<div class="toolbar"><input class="search" id="search" placeholder="ค้นหาข้อมูล..." aria-label="ค้นหาข้อมูล" value="${esc(search)}">${rooms.length?`<select id="roomFilter" aria-label="กรองห้องเรียน"><option value="">ทุกห้องเรียน</option>${rooms.map(r=>`<option ${r===roomFilter?'selected':''}>${esc(r)}</option>`).join('')}</select>`:''}${statuses.length?`<select id="statusFilter" aria-label="กรองสถานะ"><option value="">ทุกสถานะ</option>${statuses.map(s=>`<option ${s===statusFilter?'selected':''}>${esc(s)}</option>`).join('')}</select>`:''}${button(icon('download',15)+' ส่งออก CSV','export')}${write&&!readonlyKinds.includes(page)?button('นำเข้า CSV','import'):''}${button('พิมพ์','print')}${button('↻','refresh','light','aria-label="โหลดข้อมูลใหม่"')}</div><div id="tableArea"></div>`);renderTable()}
function rowActions(r){const role=store.profile.role,write=canWrite(role,page);let html=button('ดู','view','light small',`data-id="${r.id}"`);if(write)html+=button('แก้ไข','edit','light small',`data-id="${r.id}"`);if(write&&page!=='Projects')html+=button('ลบ','delete','danger small',`data-id="${r.id}"`);const s=r.data.status;let transitions=[];if(page==='Projects'){if(s==='ร่าง'&&['admin','plan_head'].includes(role))transitions=['เสนอ ผอ.'];if(s==='เสนอ ผอ.'&&['admin','director'].includes(role))transitions=['อนุมัติ','ไม่อนุมัติ'];if(s==='อนุมัติ'&&['admin','plan_head'].includes(role))transitions=['เสร็จสิ้น']}if(page==='ProjRequests'){if(s==='ยื่นแล้ว'&&['admin','plan_head'].includes(role))transitions=['เสนอ ผอ.'];if(s==='เสนอ ผอ.'&&['admin','director'].includes(role))transitions=['อนุมัติ','ปฏิเสธ'];if(s==='อนุมัติ'&&['admin','finance'].includes(role))transitions=['จ่ายแล้ว']}for(const t of transitions)html+=button(t==='จ่ายแล้ว'?'บันทึกจ่ายเงินจริง':t,'transition','yellow small',`data-id="${r.id}" data-status="${t}"`);if(['BookLoans','AssetLoans'].includes(page)&&s==='ยืมอยู่')html+=button('รับคืน','returnLoan','yellow small',`data-id="${r.id}"`);return html}
function renderTable(){const m=MODULES.find(m=>m.key===page),rows=filtered(),total=rows.length;pageIndex=Math.min(pageIndex,Math.max(0,Math.ceil(total/PAGE_SIZE)-1));const part=rows.slice(pageIndex*PAGE_SIZE,(pageIndex+1)*PAGE_SIZE);$('#tableArea').innerHTML=part.length?`<div class="tablewrap"><table><thead><tr><th>#</th>${m.columns.map(k=>`<th>${esc(label(k))}</th>`).join('')}<th>จัดการ</th></tr></thead><tbody>${part.map((r,i)=>`<tr><td style="color:var(--muted)">${pageIndex*PAGE_SIZE+i+1}</td>${m.columns.map(k=>`<td>${k==='status'?badge(r.data[k]):esc(typeof r.data[k]==='object'?JSON.stringify(r.data[k]):r.data[k]??'—')}</td>`).join('')}<td><div class="actions">${rowActions(r)}</div></td></tr>`).join('')}</tbody></table><div class="pagination"><span>${total} รายการ · หน้า ${pageIndex+1} / ${Math.max(1,Math.ceil(total/PAGE_SIZE))}</span><div class="actions">${button('← ก่อนหน้า','prev','light small',pageIndex===0?'disabled':'')}${button('ถัดไป →','next','light small',(pageIndex+1)*PAGE_SIZE>=total?'disabled':'')}</div></div></div>`:`<div class="tablewrap empty">${icon('file',38)}<h3>${search||roomFilter||statusFilter?'ไม่พบข้อมูลที่ค้นหา':'ยังไม่มีรายการในส่วนนี้'}</h3><p>${search?'ลองเปลี่ยนคำค้นหาหรือตัวกรอง':'เริ่มเพิ่มข้อมูล หรือรายการนี้อาจอยู่นอกสิทธิ์การเข้าถึงของคุณ'}</p></div>`}
function fieldInput(k,value='',kind=''){let opts=null;const val=String(value??'');if(k==='gender')opts=['ชาย','หญิง','อื่น ๆ'];if(k==='prefix')opts=['ด.ช.','ด.ญ.','นาย','นาง','นางสาว','อื่น ๆ'];if(k==='class_level')opts=['อ.1','อ.2','อ.3','ป.1','ป.2','ป.3','ป.4','ป.5','ป.6','ม.1','ม.2','ม.3','ม.4','ม.5','ม.6'];if(k==='term')opts=['1','2'];if(k==='status')opts=kind==='Students'?['กำลังศึกษา','จบการศึกษา','ย้ายออก','พักการเรียน']:kind==='Teachers'?['active','inactive']:['ร่าง','ดำเนินการ','เสร็จสิ้น'];if(k==='class_id')opts=[...new Set([...records('Students').map(r=>r.class_id),...records('Classrooms').map(r=>r.data.class_id)].filter(Boolean))].sort();if(k==='student_id'&&kind!=='Students')return `<select name="${k}" ${kind==='Scores'?'required':''}><option value="">เลือกนักเรียน</option>${records('Students').map(r=>`<option value="${esc(r.data.student_id)}" ${val===String(r.data.student_id)?'selected':''}>${esc(r.data.student_id+' · '+r.data.first_name+' '+r.data.last_name+' · '+r.class_id)}</option>`).join('')}</select>`;if(k==='teacher_id'&&kind!=='Teachers')return `<select name="${k}"><option value="">เลือกครู</option>${records('Teachers').map(r=>`<option value="${esc(r.data.teacher_id)}" ${val===r.data.teacher_id?'selected':''}>${esc(r.data.first_name+' '+r.data.last_name)}</option>`).join('')}</select>`;if(opts?.length){if(val&&!opts.includes(val))opts.unshift(val);return `<select name="${k}"><option value="">เลือก${esc(label(k))}</option>${opts.map(o=>`<option value="${esc(o)}" ${val===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`}const long=/note|description|summary|process|improve|strength|suggestion|json|answers|scores|columns|members|history|edu_list|rank_list|orders|awards|decoration|reflection|next_step|objective|problem|photos/.test(k);if(long)return `<textarea name="${k}" ${/json|answers|scores|columns/.test(k)?'placeholder="กรอกข้อมูล JSON หรือรายละเอียด"':''}>${esc(typeof value==='object'?JSON.stringify(value,null,2):value)}</textarea>`;const numeric=/^(amount|budget_|price|qty|current_stock|min_stock|max_stock|copies_|weight$|height$|total$|final_score|roll_no$|hours$|days$|credit_hours$|period$|ratio_|salary$|[ict]\d+$|total_score$)/.test(k);const date=/date$|birthdate$|license_expire$/.test(k);const type=date?'date':k.includes('email')?'email':k.includes('url')?'url':numeric?'number':'text';return `<input name="${k}" type="${type}" value="${esc(val)}" ${numeric?'min="0" step="any"':''} ${kind==='Scores'&&k==='total'?'required max="100"':''} ${(k==='grade'&&kind==='Scores')||k==='current_stock'||(k==='copies_available'&&kind==='Books')?'readonly':''} ${['first_name','student_id','teacher_id','name','title'].includes(k)?'maxlength="250"':''}>`}
function editRecord(id=null,view=false){const m=MODULES.find(m=>m.key===page),old=id?store.records.find(r=>r.id===id):null;const data=old?.data||{academic_year:store.settings.academic_year,...(page==='Students'?{status:'กำลังศึกษา',room:'1'}:{}),...(page==='Teachers'?{status:'active'}:{}),...(page==='Projects'?{status:'ร่าง',budget_alloc:0,budget_activity:0}:{})};let fields=m.fields.filter(k=>!['approved_by','approved_date','proposed_by','proposed_date','completed_by','completed_date','paid_by','paid_date','propose_by','propose_date','reviewed_by','reviewed_at','reviewer_name'].includes(k));if(page==='Students')fields=['student_id',...fields.filter(k=>k!=='student_id')];if(page==='Teachers')fields=['teacher_id',...fields.filter(k=>k!=='teacher_id')];const form=`<form id="recordForm" data-id="${old?.id||''}" class="formgrid">${fields.map(k=>`<div class="field ${/note|description|summary|json|process/.test(k)?'full':''}"><label for="field_${k}">${esc(label(k))}</label>${view?`<div style="padding:9px 0;white-space:pre-wrap;overflow-wrap:anywhere">${k==='status'?badge(data[k]):esc(typeof data[k]==='object'?JSON.stringify(data[k],null,2):data[k]??'—')}</div>`:page==='Projects'&&k==='status'?`<input name="status" value="${esc(data.status)}" readonly>`:fieldInput(k,data[k]??'',page).replace(/<(input|select|textarea) /,'<$1 id="field_'+k+'" ')}</div>`).join('')}<div id="formErr" class="err field full" role="alert"></div></form>`;modal((view?'รายละเอียด':old?'แก้ไข':'เพิ่ม')+' · '+m.title,form,button('ปิด','close')+(!view?'<button class="btn" type="submit" form="recordForm">บันทึกข้อมูล</button>':''))}
async function saveForm(form){const m=MODULES.find(m=>m.key===page),old=store.records.find(r=>r.id===form.dataset.id);let data={...old?.data,...Object.fromEntries(new FormData(form))};if(['Students','Teachers'].includes(page)&&!data[page==='Students'?'student_id':'teacher_id'])throw Error('กรุณากรอกรหัส');if(!old&&page==='Projects')data.status='ร่าง';const student=records('Students').find(s=>String(s.data.student_id)===String(data.student_id));if(student&&page!=='Students'){data.student_name=student.data.first_name+' '+student.data.last_name;data.class_id=student.class_id}const teacher=records('Teachers').find(t=>String(t.data.teacher_id)===String(data.teacher_id));if(teacher&&page!=='Teachers')data.teacher_name=teacher.data.first_name+' '+teacher.data.last_name;validateData(page,data);if(data.class_level&&!data.room)data.room='1';await saveRecord(m.key,data,old);await reload();closeModal();toast('บันทึกข้อมูลเรียบร้อยแล้ว')}
function configure(){modal('เชื่อมต่อ Supabase',`<p class="help">ใช้ Project URL และ Publishable key จาก Supabase · ระบบไม่รับ service_role หรือ Secret key ในหน้าเว็บ</p><form id="configForm" class="formgrid"><div class="field full"><label for="supabaseUrl">Project URL</label><input id="supabaseUrl" name="supabaseUrl" placeholder="https://xxxxxxxx.supabase.co" type="url" value="${esc(store.config.supabaseUrl||'')}" required></div><div class="field full"><label for="supabaseAnonKey">Publishable key / anon key</label><input id="supabaseAnonKey" name="supabaseAnonKey" value="${esc(store.config.supabaseAnonKey||'')}" placeholder="sb_publishable_..." required autocomplete="off"></div><div class="field full"><p class="help">ก่อนเข้าสู่ระบบ ต้องติดตั้ง schema.sql และสร้างผู้ดูแลระบบใน Supabase แล้ว การตั้งค่านี้บันทึกเฉพาะเบราว์เซอร์เครื่องนี้</p><a href="schema.sql" download="samakkee-schema.sql">ดาวน์โหลดโครงสร้างฐานข้อมูล SQL</a></div><div id="formErr" class="err field full" role="alert"></div></form>`,button('ยกเลิก','close')+'<button class="btn" type="submit" form="configForm">บันทึกและทดสอบการเชื่อมต่อ</button>')}
function settings(){setContent(head('ตั้งค่าระบบ','การเชื่อมต่อ ฐานข้อมูล และข้อมูลโรงเรียน')+`<div class="settingsgrid"><section class="card"><div class="cardhead"><h2>ข้อมูลโรงเรียน</h2>${icon('settings')}</div><form id="settingsForm" class="formgrid"><div class="field full"><label>ชื่อโรงเรียน</label><input name="school_name" value="${esc(store.settings.school_name)}" readonly></div><div class="field"><label>ปีการศึกษาที่ใช้งาน</label><input name="academic_year" pattern="[0-9]{4}" required value="${esc(store.settings.academic_year)}"></div><div class="field"><label>ชื่อผู้อำนวยการ</label><input name="director_name" value="${esc(store.settings.director_name)}"></div><p class="help field full">การเปลี่ยนปีการศึกษาจะเปลี่ยนชุดข้อมูลที่แสดง ไม่เลื่อนชั้นหรือย้ายข้อมูลเดิมโดยอัตโนมัติ</p><div id="settingsErr" class="err field full"></div><div class="field full"><button class="btn" ${store.profile.role!=='admin'?'disabled':''}>บันทึกการตั้งค่า</button></div></form></section><section class="card"><div class="cardhead"><h2>สถานะการติดตั้ง</h2>${icon('shield')}</div><div class="setting-step"><span class="stepnum">1</span><div><strong>Supabase Database + Auth</strong><p>${store.demo?'ยังอยู่ในโหมดสาธิต':'เชื่อมต่อและตรวจสอบเซสชันแล้ว'}</p></div></div><div class="setting-step"><span class="stepnum">2</span><div><strong>GitHub Repository</strong><p>การเชื่อมบัญชี GitHub ต้องดำเนินการผ่านเจ้าของบัญชี</p><p class="help">ไฟล์ต้นฉบับมี workflow สำหรับเผยแพร่ GitHub Pages แล้ว</p></div></div><div class="setting-step"><span class="stepnum">3</span><div><strong>การควบคุมข้อมูล</strong><p>ยืนยันตัวตนด้วย Supabase Auth และกำหนดสิทธิ์ผ่าน RLS</p></div></div>${button('ตั้งค่าการเชื่อมต่อ','configure')} <a class="btn light" href="schema.sql" download>ดาวน์โหลด SQL</a></section></div><section class="card"><h2>ขอบเขตระบบรุ่นแรก</h2><p class="help">ระบบมีแบบฟอร์มทะเบียน 49 หมวด เช็กชื่อรายห้อง คำขออนุมัติโครงการ / เบิกจ่าย เงินออม วัสดุ และการยืมคืน ส่วนแบบประเมิน SDQ, LD, EQ และเอกสารราชการเป็นแบบฟอร์มบันทึกข้อมูล ยังไม่มีชุดเกณฑ์ประเมินอัตโนมัติหรือรูปแบบเอกสาร ปพ.5 / ปพ.6 ที่ตรวจรับตามแบบของโรงเรียน</p></section>`)}
function reports(){const kinds=['Students','Teachers','Attendance','Scores','Projects','ProjExpenses','Savings','Assets'];setContent(head('รายงานและสถิติ','สรุปจากข้อมูลที่คุณมีสิทธิ์เข้าถึง · ส่งออกหรือพิมพ์ได้',button('พิมพ์รายงาน','print'))+`<div class="modulecards">${kinds.map(k=>`<button class="modulecard" data-page="${k}">${micon(k)}<h3>${MODULES.find(m=>m.key===k).title}</h3><p>${records(k).length} รายการ · เปิดตารางและส่งออก CSV →</p></button>`).join('')}</div><section class="card" style="margin-top:25px"><div class="cardhead"><h2>สรุปคะแนนผลการเรียน</h2><small>รายวิชา / ภาคเรียน ตามข้อมูลที่บันทึก</small></div><div class="tablewrap"><table><thead><tr><th>รหัสนักเรียน</th><th>ชื่อ–สกุล</th><th>ห้อง</th><th>รายวิชา / การมอบหมาย</th><th>คะแนนรวม</th><th>ผลการเรียน</th></tr></thead><tbody>${records('Scores').map(r=>`<tr><td>${esc(r.data.student_id)}</td><td>${esc(r.data.student_name)}</td><td>${esc(r.class_id)}</td><td>${esc(r.data.subject_name||r.data.assign_id)}</td><td>${esc(r.data.total)}</td><td>${esc(r.data.grade)}</td></tr>`).join('')||'<tr><td colspan="6" style="text-align:center">ยังไม่มีข้อมูลคะแนน</td></tr>'}</tbody></table></div><p class="help">รายงานนี้เป็นสรุปผลการเรียนภายใน ไม่ใช่แบบเอกสารราชการ ปพ.5 / ปพ.6 ฉบับสมบูรณ์</p></section>`)}
async function users(){setContent(head('ผู้ใช้และสิทธิ์','บัญชีใหม่เริ่มต้นในสถานะรออนุมัติ · เฉพาะผู้ดูแลระบบกำหนดสิทธิ์ได้'));if(store.demo){$('#content').insertAdjacentHTML('beforeend','<section class="card"><p>โหมดสาธิตไม่เชื่อมกับบัญชีผู้ใช้จริง</p></section>');return}const people=await request('/rest/v1/school_profiles?select=*&order=created_at.desc');$('#content').insertAdjacentHTML('beforeend',`<div class="tablewrap"><table><thead><tr><th>ชื่อผู้ใช้</th><th>บทบาท</th><th>ห้องประจำชั้น</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>${people.map(p=>`<tr><td>${esc(p.display_name||p.id)}</td><td>${esc(ROLES[p.role])}</td><td>${esc(p.homeroom||'—')}</td><td>${badge(p.active?'ใช้งาน':'ระงับ')}</td><td>${store.profile.role==='admin'&&p.id!==store.profile.id?button('กำหนดสิทธิ์','role','light small',`data-id="${p.id}" data-role="${esc(p.role)}" data-room="${esc(p.homeroom)}" data-active="${p.active}"`):'—'}</td></tr>`).join('')}</tbody></table></div>`)}
async function audit(){setContent(head('ประวัติการใช้งาน','บันทึกการเพิ่ม แก้ไข ลบข้อมูล และเปลี่ยนสิทธิ์จากฐานข้อมูล'));if(store.demo){$('#content').insertAdjacentHTML('beforeend','<section class="card">ประวัติจริงจะแสดงเมื่อเชื่อมต่อ Supabase</section>');return}const logs=await request('/rest/v1/school_audit?select=*&order=created_at.desc&limit=200');$('#content').insertAdjacentHTML('beforeend',`<div class="tablewrap"><table><thead><tr><th>เวลา</th><th>การกระทำ</th><th>ระบบงาน</th><th>ผู้ใช้ (UUID)</th></tr></thead><tbody>${logs.map(l=>`<tr><td>${esc(new Date(l.created_at).toLocaleString('th-TH'))}</td><td>${esc(l.action)}</td><td>${esc(MODULES.find(m=>m.key===l.record_type)?.title||l.record_type)}</td><td>${esc(l.actor)}</td></tr>`).join('')}</tbody></table></div>`)}
async function render(){if(!store.profile){login();return}if(store.profile.role==='pending'){pendingPage();return}shell();if(page==='dashboard')dashboard();else if(page==='modules')allModules();else if(page==='settings')settings();else if(page==='reports')reports();else if(page==='users')await users();else if(page==='audit')await audit();else modulePage()}
function pendingPage(){$('#app').innerHTML=`<main class="login-form" style="min-height:100vh"><section class="card" style="max-width:530px;text-align:center;padding:40px">${icon('clock',40)}<h2 style="margin-top:18px">บัญชีอยู่ระหว่างรออนุมัติ</h2><p class="sub">${esc(store.profile.display_name||store.profile.email)}<br>ให้ผู้ดูแลโรงเรียนกำหนดบทบาทและห้องประจำชั้นก่อนใช้งาน</p><p class="help" style="margin:20px 0">หากคุณเป็นผู้ติดตั้งระบบคนแรก ให้เจ้าของโปรเจกต์กำหนดสิทธิ์ admin ให้บัญชีอีเมลที่คุณยืนยันใน Supabase แล้ว</p>${button('ตรวจสอบสิทธิ์อีกครั้ง','checkAccess')}${button('ออกจากระบบ','logout')}</section></main>`}
async function reload(){await loadRecords();await render()}
async function navigate(target){page=target;search='';roomFilter='';statusFilter='';pageIndex=0;await render();window.scrollTo(0,0)}
function exportCSV(template=false){const m=MODULES.find(m=>m.key===page),cols=m.fields;const rows=template?[]:filtered().map(r=>cols.map(k=>csvCell(r.data[k]??'')));const csv='\uFEFF'+[cols.map(csvCell).join(','),...rows.map(r=>r.join(','))].join('\r\n');download(csv,`${page}-${store.settings.academic_year}${template?'-template':''}.csv`,'text/csv;charset=utf-8')}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function importModal(){modal('นำเข้าข้อมูล CSV',`<p class="help">หัวคอลัมน์ใช้ชื่อฟิลด์ภาษาอังกฤษตามไฟล์ต้นแบบ · นำเข้าครั้งละไม่เกิน 500 แถว · ระบบจะตรวจข้อมูลทุกแถวก่อนส่ง และบันทึกทั้งหมดในคำขอเดียว</p>${button('ดาวน์โหลดไฟล์ต้นแบบ','template')}<form id="importForm" style="margin-top:20px"><input name="file" type="file" accept=".csv,text/csv" required><p class="help">ไฟล์ต้องเป็น UTF-8 · เลขประจำตัวที่มีศูนย์นำหน้าควรกำหนดเป็นข้อความ</p><div id="formErr" class="err"></div></form>`,button('ยกเลิก','close')+'<button class="btn" form="importForm">ตรวจสอบและนำเข้า</button>')}
function attendance(){const rooms=[...new Set(records('Students').map(r=>r.class_id))].filter(Boolean).sort();modal('เช็กชื่อนักเรียนรายห้อง',`<form id="attendanceForm"><div class="toolbar"><div class="field"><label>วันที่</label><input type="date" name="date" required value="${today()}"></div><div class="field"><label>ห้องเรียน</label><select name="class_id" id="attRoom" required><option value="">เลือกห้องเรียน</option>${rooms.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div></div><div id="attStudents" style="overflow:auto"></div><div id="formErr" class="err"></div></form>`,button('ยกเลิก','close')+'<button class="btn" form="attendanceForm">บันทึกการเช็กชื่อ</button>',true)}
function attendanceRows(){const form=$('#attendanceForm'),room=form.elements.class_id.value,date=form.elements.date.value;const old=records('Attendance').find(r=>r.class_id===room&&r.data.date===date);let marks={};try{marks=JSON.parse(old?.data.marks||'{}')}catch{}const students=records('Students').filter(r=>r.class_id===room&&r.data.status==='กำลังศึกษา').sort((a,b)=>Number(a.data.roll_no)-Number(b.data.roll_no));$('#attStudents').innerHTML=students.length?`<table><thead><tr><th>เลขที่</th><th>นักเรียน</th><th>สถานะการมาเรียน</th></tr></thead><tbody>${students.map(s=>`<tr><td>${esc(s.data.roll_no||'—')}</td><td>${esc(s.data.first_name+' '+s.data.last_name)}</td><td><div class="attrow">${['มา','สาย','ลา','ขาด'].map(status=>`<label><input type="radio" name="mark_${s.id}" value="${status}" ${(marks[s.data.student_id]||'มา')===status?'checked':''}>${status}</label>`).join('')}</div></td></tr>`).join('')}</tbody></table>`:'<p class="help">ยังไม่มีนักเรียนสถานะกำลังศึกษาในห้องนี้</p>'}
function requestModal(){const ps=records('Projects').filter(r=>r.data.status==='อนุมัติ');modal('ยื่นคำขอเบิกจ่าย',`<form id="requestForm" class="formgrid"><div class="field full"><label>โครงการที่ได้รับอนุมัติ</label><select name="project_id" required><option value="">เลือกโครงการ</option>${ps.map(p=>`<option value="${p.id}">${esc(p.data.name)}</option>`).join('')}</select></div><div class="field full"><label>รายละเอียดการขอเบิก</label><textarea name="description" required maxlength="2000"></textarea></div><div class="field"><label>จำนวนเงิน (บาท)</label><input name="amount" type="number" required min="0.01" max="1000000000" step="0.01"></div><p class="help field full">คำขอจะส่งให้หัวหน้าแผนงานเสนอผู้อำนวยการ ก่อนงานการเงินบันทึกจ่ายจริง</p><div id="formErr" class="err field full"></div></form>`,button('ยกเลิก','close')+'<button class="btn" form="requestForm">ยื่นคำขอ</button>')}
function savingsModal(){modal('ฝาก / ถอนเงินออมนักเรียน',`<form id="savingForm" class="formgrid"><div class="field full"><label>นักเรียน</label><select name="student_record_id" required><option value="">เลือกนักเรียน</option>${records('Students').map(s=>`<option value="${s.id}">${esc(s.data.student_id+' · '+s.data.first_name+' '+s.data.last_name+' · '+s.class_id)}</option>`).join('')}</select></div><div class="field"><label>ประเภทรายการ</label><select name="txn_type"><option>ฝาก</option><option>ถอน</option></select></div><div class="field"><label>จำนวนเงิน</label><input name="amount" type="number" min="0.01" step="0.01" required></div><div class="field full"><label>หมายเหตุ</label><input name="memo"></div><div id="formErr" class="err field full"></div></form>`,button('ยกเลิก','close')+'<button class="btn" form="savingForm">บันทึกรายการ</button>')}
function roleModal(b){modal('กำหนดสิทธิ์ผู้ใช้',`<form id="roleForm" class="formgrid" data-id="${b.dataset.id}"><div class="field"><label>บทบาท</label><select name="new_role">${Object.entries(ROLES).map(([v,t])=>`<option value="${v}" ${v===b.dataset.role?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>ห้องประจำชั้น เช่น ป.1/1</label><input name="room" value="${esc(b.dataset.room)}"></div><div class="field"><label>การเข้าถึงระบบ</label><select name="enabled"><option value="true">ใช้งาน</option><option value="false" ${b.dataset.active==='false'?'selected':''}>ระงับ</option></select></div><div id="formErr" class="err field full"></div></form>`,button('ยกเลิก','close')+'<button class="btn" form="roleForm">บันทึกสิทธิ์</button>')}
function supplyModal(){modal('รับ / จ่ายวัสดุ',`<form id="supplyForm" class="formgrid"><div class="field full"><label>รายการวัสดุ</label><select name="supply_id" required><option value="">เลือกวัสดุ</option>${records('Supplies').map(s=>`<option value="${s.id}">${esc(s.data.name+' · คงเหลือ '+(s.data.current_stock||0)+' '+(s.data.unit||''))}</option>`).join('')}</select></div><div class="field"><label>ประเภทรายการ</label><select name="txn_type"><option>รับ</option><option>จ่าย</option></select></div><div class="field"><label>จำนวน</label><input name="quantity" type="number" min="0.01" step="0.01" required></div><div class="field"><label>ราคาต่อหน่วย (เมื่อรับ)</label><input name="price" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>รายละเอียด / ผู้รับ</label><input name="memo"></div><p class="help field full">การจ่ายวัสดุคำนวณต้นทุนจากล็อตที่รับก่อน (FIFO) และไม่อนุญาตให้จ่ายเกินยอดคงเหลือ</p><div id="formErr" class="err field full"></div></form>`,button('ยกเลิก','close')+'<button class="btn" form="supplyForm">บันทึกการรับ / จ่าย</button>')}
function loanModal(){const kind=page==='BookLoans'?'Books':'Assets';modal('บันทึกการยืม'+(kind==='Books'?'หนังสือ':'ครุภัณฑ์'),`<form id="loanForm" class="formgrid"><div class="field full"><label>รายการที่ยืม</label><select name="item_id" required><option value="">เลือกรายการ</option>${records(kind).map(s=>`<option value="${s.id}">${esc(s.data.title||s.data.name)}</option>`).join('')}</select></div><div class="field"><label>ชื่อผู้ยืม</label><input name="borrower" required value="${esc(store.profile.display_name)}"></div><div class="field"><label>กำหนดคืน</label><input name="due_date" type="date" min="${today()}" required></div><div id="formErr" class="err field full"></div></form>`,button('ยกเลิก','close')+'<button class="btn" form="loanForm">บันทึกการยืม</button>')}
function demoAdd(kind,data){return saveRecord(kind,data)}
async function demoTransition(r,next){if(page==='ProjRequests'&&next==='จ่ายแล้ว'){const p=store.records.find(p=>p.id===r.data.proj_id);const used=records('ProjExpenses').filter(e=>e.data.proj_id===p.id).reduce((a,e)=>a+Number(e.data.amount),0);const balance=Number(p.data.budget_alloc||0)+Number(p.data.budget_activity||0)-used,amount=Number(r.data.amount_request);if(amount>balance)throw Error('งบประมาณคงเหลือไม่เพียงพอ');await demoAdd('ProjExpenses',{proj_id:p.id,proj_name:p.data.name,request_id:r.id,description:r.data.description,amount,expense_date:today(),balance_after:balance-amount})}r.data.status=next}
async function submit(form){const data=Object.fromEntries(new FormData(form));switch(form.id){case 'loginForm':if(loginMode==='login'){await signIn(data.email,data.password);await loadRecords();await render()}else{await signUp(data.email,data.password,data.display_name);loginMode='login';login();toast('ส่งคำขอแล้ว กรุณาตรวจอีเมลยืนยันและให้ผู้ดูแลกำหนดสิทธิ์')}break;
case 'configForm':{const config={supabaseUrl:data.supabaseUrl.replace(/\/$/,''),supabaseAnonKey:data.supabaseAnonKey.trim()};const {validConfig}=await import('./core.js');if(!validConfig(config))throw Error('Project URL หรือ Publishable key ไม่ถูกต้อง · ห้ามใช้ Secret key');const res=await fetch(config.supabaseUrl+'/auth/v1/settings',{headers:{apikey:config.supabaseAnonKey},signal:AbortSignal.timeout(15000)});if(!res.ok)throw Error('เชื่อมต่อ Supabase ไม่สำเร็จ กรุณาตรวจสอบ URL และ key');saveConfig(config);closeModal();login();toast('เชื่อมต่อ Supabase สำเร็จ กรุณาเข้าสู่ระบบ');break}
case 'recordForm':await saveForm(form);break;
case 'settingsForm':if(!store.demo){const result=await request('/rest/v1/school_settings?id=eq.true',{method:'PATCH',body:data,headers:{Prefer:'return=representation'}});if(!result?.length)throw Error('ไม่มีสิทธิ์เปลี่ยนการตั้งค่า')}store.settings={...store.settings,...data};await reload();toast('บันทึกการตั้งค่าแล้ว');break;
case 'importForm':{const file=form.elements.file.files[0];if(file.size>2*1024*1024)throw Error('ไฟล์ต้องมีขนาดไม่เกิน 2 MB');const parsed=parseCSV(await file.text()),columns=parsed.shift();if(!columns?.length||!parsed.length)throw Error('ไม่พบแถวข้อมูลใน CSV');if(parsed.length>500)throw Error('นำเข้าได้ครั้งละไม่เกิน 500 แถว');const m=MODULES.find(m=>m.key===page);if(columns.some(c=>!m.fields.includes(c)))throw Error('ชื่อคอลัมน์ไม่ตรงกับต้นแบบ กรุณาดาวน์โหลดไฟล์ต้นแบบ');const batch=parsed.map((row,i)=>{if(row.length!==columns.length)throw Error('จำนวนคอลัมน์ไม่ตรงที่แถว '+(i+2));const d=Object.fromEntries(columns.map((c,j)=>[c,row[j]]));try{validateData(page,d)}catch(e){throw Error('แถว '+(i+2)+': '+e.message)}return {record_type:page,academic_year:String(d.academic_year||store.settings.academic_year),class_id:d.class_id||(d.class_level?d.class_level+'/'+(d.room||'1'):''),data:d}});if(store.demo){for(const b of batch)await saveRecord(page,b.data)}else await request('/rest/v1/school_records',{method:'POST',body:batch});await reload();closeModal();toast('นำเข้าข้อมูล '+batch.length+' รายการเรียบร้อยแล้ว');break}
case 'attendanceForm':{if(!data.class_id)throw Error('กรุณาเลือกห้องเรียน');const students=records('Students').filter(r=>r.class_id===data.class_id&&r.data.status==='กำลังศึกษา');if(!students.length)throw Error('ไม่มีนักเรียนในห้องนี้');const marks={};for(const s of students)marks[s.data.student_id]=data['mark_'+s.id];const count=s=>Object.values(marks).filter(v=>v===s).length;const d={date:data.date,class_id:data.class_id,total:students.length,present:count('มา'),late:count('สาย'),leave:count('ลา'),absent:count('ขาด'),marks:JSON.stringify(marks),academic_year:store.settings.academic_year};const old=records('Attendance').find(r=>r.class_id===data.class_id&&r.data.date===data.date);await saveRecord('Attendance',d,old);await reload();closeModal();toast('บันทึกการเช็กชื่อเรียบร้อยแล้ว');break}
case 'requestForm':if(store.demo){const p=store.records.find(r=>r.id===data.project_id);await demoAdd('ProjRequests',{proj_id:p.id,proj_name:p.data.name,description:data.description,amount_request:Number(data.amount),status:'ยื่นแล้ว',request_date:today(),requested_name:store.profile.display_name})}else await rpc('school_submit_request',{...data,amount:Number(data.amount)});await reload();closeModal();toast('ยื่นคำขอเรียบร้อยแล้ว');break;
case 'savingForm':if(store.demo){const s=store.records.find(s=>s.id===data.student_record_id);const old=records('Savings').filter(r=>r.data.student_id===s.data.student_id);const balance=old.reduce((a,r)=>a+(r.data.txn_type==='ฝาก'?1:-1)*Number(r.data.amount),0)+(data.txn_type==='ฝาก'?1:-1)*Number(data.amount);if(balance<0)throw Error('ยอดเงินออมไม่เพียงพอ');await demoAdd('Savings',{student_id:s.data.student_id,student_name:s.data.first_name+' '+s.data.last_name,class_id:s.class_id,amount:Number(data.amount),txn_type:data.txn_type,txn_date:today(),balance_after:balance,note:data.memo})}else await rpc('school_savings',{...data,amount:Number(data.amount)});await reload();closeModal();toast('บันทึกธุรกรรมเงินออมแล้ว');break;
case 'roleForm':await rpc('school_set_role',{...data,target:form.dataset.id,enabled:data.enabled==='true'});closeModal();await render();toast('บันทึกสิทธิ์ผู้ใช้เรียบร้อยแล้ว');break;
case 'supplyForm':if(store.demo){const s=store.records.find(s=>s.id===data.supply_id),qty=Number(data.quantity),stock=Number(s.data.current_stock)+(data.txn_type==='รับ'?qty:-qty);if(stock<0)throw Error('วัสดุคงเหลือไม่พอ');s.data.current_stock=stock;await demoAdd('SupplyTransactions',{supply_id:s.id,supply_name:s.data.name,txn_type:data.txn_type,qty,unit_price:data.price,purpose:data.memo,txn_date:today()})}else await rpc('school_supply',{...data,quantity:Number(data.quantity),price:Number(data.price)});await reload();closeModal();toast('บันทึกการรับ / จ่ายวัสดุแล้ว');break;
case 'loanForm':if(store.demo){const item=store.records.find(r=>r.id===data.item_id);if(item.record_type==='Books'){if(Number(item.data.copies_available)<1)throw Error('หนังสือไม่เหลือให้ยืม');item.data.copies_available--}else if(records('AssetLoans').some(r=>r.data.item_id===item.id&&r.data.status==='ยืมอยู่'))throw Error('ครุภัณฑ์นี้ถูกยืมอยู่');await demoAdd(page,{item_id:item.id,book_title:item.data.title,asset_name:item.data.name,borrower_name:data.borrower,due_date:data.due_date,borrow_date:today(),loan_date:today(),status:'ยืมอยู่'})}else await rpc('school_borrow',data);await reload();closeModal();toast('บันทึกการยืมแล้ว');break}}
document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const form=e.target;busy=true;const submitButton=document.querySelector(`[form="${form.id}"]`)||form.querySelector('button[type=submit],button:not([type])');if(submitButton)submitButton.disabled=true;try{await submit(form)}catch(err){const el=form.querySelector('.err');if(el)el.textContent=humanError(err);else toast(humanError(err))}finally{busy=false;if(submitButton?.isConnected)submitButton.disabled=false}});
function humanError(err){const s=err.message||String(err);if(/Invalid login credentials/i.test(s))return 'อีเมลหรือรหัสผ่านไม่ถูกต้อง';if(/Email not confirmed/i.test(s))return 'กรุณายืนยันอีเมลก่อนเข้าสู่ระบบ';if(/row-level security|permission denied|permission/i.test(s))return 'คุณไม่มีสิทธิ์ดำเนินการในส่วนนี้';if(/duplicate key/i.test(s))return 'พบรหัสหรือรายการซ้ำในระบบ กรุณาตรวจสอบข้อมูล';if(/Insufficient/i.test(s))return 'ยอดคงเหลือไม่เพียงพอ กรุณาตรวจสอบก่อนทำรายการ';if(/Invalid transition/i.test(s))return 'สถานะเปลี่ยนไปแล้วหรือคุณไม่มีสิทธิ์อนุมัติ กรุณาโหลดข้อมูลใหม่';if(/Abort|timeout/i.test(s))return 'การเชื่อมต่อใช้เวลานาน กรุณาโหลดข้อมูลตรวจสอบก่อนทำรายการซ้ำ';return s}
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;pageIndex=0;renderTable()}if(e.target.name==='total'&&page==='Scores'&&e.target.form?.elements.grade)e.target.form.elements.grade.value=grade(e.target.value)});
document.addEventListener('change',e=>{if(e.target.id==='roomFilter'){roomFilter=e.target.value;pageIndex=0;renderTable()}if(e.target.id==='statusFilter'){statusFilter=e.target.value;pageIndex=0;renderTable()}if(e.target.id==='attRoom'||(e.target.name==='date'&&e.target.form?.id==='attendanceForm'))attendanceRows()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('.sidebar')?.classList.remove('open')}if(e.key==='Tab'&&$('#modal .modalbox')){const focusables=[...document.querySelectorAll('#modal button:not(:disabled),#modal input:not(:disabled),#modal select:not(:disabled),#modal textarea:not(:disabled),#modal a[href]')];if(e.shiftKey&&document.activeElement===focusables[0]){e.preventDefault();focusables.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===focusables.at(-1)){e.preventDefault();focusables[0]?.focus()}}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-act],[data-page]');if(!b||busy)return;try{if(b.dataset.page){await navigate(b.dataset.page);return}const id=b.dataset.id,r=store.records.find(r=>r.id===id);switch(b.dataset.act){case 'demo':startDemo();page='dashboard';await render();break;case 'configure':configure();break;case 'switchLogin':loginMode=loginMode==='login'?'signup':'login';login();break;case 'logout':await signOut();closeModal();login();break;case 'checkAccess':await restore();await loadRecords();await render();break;case 'close':closeModal();break;case 'menu':$('.sidebar').classList.toggle('open');break;case 'nav':await navigate(b.dataset.target);break;case 'new':editRecord();break;case 'view':editRecord(id,true);break;case 'edit':editRecord(id);break;case 'delete':modal('ยืนยันการลบข้อมูล',`<p>ต้องการลบรายการนี้หรือไม่?</p><p class="help">การลบจะถูกบันทึกในประวัติการใช้งาน หากมีข้อมูลที่อ้างอิงอยู่ระบบจะไม่อนุญาตให้ลบ</p>`,button('ยกเลิก','close')+button('ยืนยันลบ','confirmDelete','danger',`data-id="${id}"`));break;case 'confirmDelete':await deleteRecord(r);await reload();closeModal();toast('ลบข้อมูลเรียบร้อยแล้ว');break;case 'prev':pageIndex--;renderTable();break;case 'next':pageIndex++;renderTable();break;case 'print':window.print();break;case 'export':exportCSV();break;case 'template':exportCSV(true);break;case 'import':importModal();break;case 'attendance':attendance();break;case 'newRequest':requestModal();break;case 'saving':savingsModal();break;case 'supply':supplyModal();break;case 'loan':loanModal();break;case 'role':roleModal(b);break;case 'refresh':b.disabled=true;await reload();toast('โหลดข้อมูลล่าสุดแล้ว');break;
case 'transition':modal('ยืนยันการเปลี่ยนสถานะ',`<p>เปลี่ยนสถานะรายการเป็น <strong>${esc(b.dataset.status)}</strong></p>${b.dataset.status==='จ่ายแล้ว'?'<p class="help">ขั้นตอนนี้จะบันทึกรายการจ่ายเงินจริงและตัดงบประมาณโครงการ</p>':''}`,button('ยกเลิก','close')+button('ยืนยัน','confirmTransition','',`data-id="${id}" data-status="${esc(b.dataset.status)}"`));break;
case 'confirmTransition':busy=true;b.disabled=true;if(store.demo)await demoTransition(r,b.dataset.status);else await rpc(page==='Projects'?'school_transition_project':'school_transition_request',{[page==='Projects'?'project_id':'request_id']:id,next_status:b.dataset.status});await reload();closeModal();toast('เปลี่ยนสถานะเรียบร้อยแล้ว');break;
case 'returnLoan':busy=true;b.disabled=true;if(store.demo){r.data.status='คืนแล้ว';r.data.return_date=today();const item=store.records.find(x=>x.id===r.data.item_id);if(item?.record_type==='Books')item.data.copies_available++}else await rpc('school_return',{loan_id:id});await reload();toast('บันทึกการคืนเรียบร้อยแล้ว');break}
}catch(err){toast(humanError(err))}finally{busy=false;if(b.isConnected)b.disabled=false}});
(async()=>{try{if(store.session&&configured()){await restore();if(store.profile.role!=='pending')await loadRecords()}await render()}catch(e){await signOut();login();$('#loginErr').textContent=humanError(e)}})();
